INSERT INTO `categories` (`id`, `name`, `slug`, `tagline`, `description`, `created_at`, `updated_at`, `image`, `badge`, `group`, `regions`, `tags`, `artisans_count`) VALUES
(1, 'Tenun & Wastra Tradisi', 'tenun-wastra-tradisi', 'Tenun & Songket Tradisional', 'Tenun Ikat Sumba dengan motif kuda dan pohon tengkorak, kemewahan Songket Pandai Sikek benang emas, Tenun Troso berpola modern, dan Ulos Batak bernilai sakral. Ditenun secara sabar menggunakan alat tenun bukan mesin (ATBM) dan gedogan turun-temurun.', '2026-11-03 08:17:18', '2026-11-10 05:43:36', , 'Wastra Tradisi', 'Wastra Benang', 'SUMBA, MINANGKABAU, JEPARA, SUMUT', 'Tenun Ikat Sumba, Songket Pandai Sikek, Tenun Troso, Ulos Batak', 340);
INSERT INTO `categories` (`id`, `name`, `slug`, `tagline`, `description`, `created_at`, `updated_at`, `image`, `badge`, `group`, `regions`, `tags`, `artisans_count`) VALUES
(2, 'Batik Tulis Canting', 'batik-tulis-canting', 'Batik Warisan Luhur', 'Batik Tulis canting tembaga halus dan Batik Cap presisi tinggi. Mengutamakan bahan pewarna alami dari daun Indigofera, kulit kayu Tingi, dan serbuk Jambal ramah lingkungan.', '2026-11-03 08:17:18', '2026-11-10 05:43:36', , 'Pewarna Alami Tingi & Indigo', 'Wastra Benang', 'SOLO, YOGYAKARTA, PEKALONGAN, LASEM', 'Batik Tulis Alusan, Pewarna Indigo Alami, Batik Cap Klasik', 480);
INSERT INTO `categories` (`id`, `name`, `slug`, `tagline`, `description`, `created_at`, `updated_at`, `image`, `badge`, `group`, `regions`, `tags`, `artisans_count`) VALUES
(3, 'Gerabah & Keramik Tanah', 'gerabah-keramik-tanah', 'Gerabah & Keramik Tradisi', 'Peralatan makan tanah liat Kasongan Bantul, teknik pembakaran sekam Banyumulek Lombok Barat, dan keramik glasir fungsional Plered Purwakarta.', '2026-11-03 08:17:18', '2026-11-10 05:43:36', , NULL, 'Tanah Liat & Keramik', 'KASONGAN, BANYUMULEK, PLERED', NULL, 195);
INSERT INTO `categories` (`id`, `name`, `slug`, `tagline`, `description`, `created_at`, `updated_at`, `image`, `badge`, `group`, `regions`, `tags`, `artisans_count`) VALUES
(4, 'Ukiran & Pahat Kayu', 'ukiran-pahat-kayu', 'Seni Ukir & Pahat Kayu', 'Ukiran tembus Jepara, ornamen arca spiritual Gianyar Bali, ukiran tiang leluhur suku Asmat Papua, serta panel motif Pa\'tedong khas Toraja berkayu jati perhutani lestari.', '2026-11-03 08:17:18', '2026-11-10 05:43:36', , NULL, 'Kayu & Ukiran', 'JEPARA, GIANYAR, ASMAT, TORAJA', NULL, 160);
INSERT INTO `categories` (`id`, `name`, `slug`, `tagline`, `description`, `created_at`, `updated_at`, `image`, `badge`, `group`, `regions`, `tags`, `artisans_count`) VALUES
(5, 'Anyaman Rotan & Serat', 'anyaman-rotan-serat', 'Anyaman Serat & Rotan', 'Anyaman daun lontar Rote Ndao yang tahan puluhan tahun, tas rotan anyam Dayak, kerajinan mendong dan pandan Tasikmalaya, serta besek bambu halus Sleman.', '2026-11-03 08:17:18', '2026-11-10 05:43:36', , NULL, 'Anyaman Serat', 'ROTE, DAYAK KALTIM, TASIKMALAYA, SLEMAN', NULL, 210);
INSERT INTO `categories` (`id`, `name`, `slug`, `tagline`, `description`, `created_at`, `updated_at`, `image`, `badge`, `group`, `regions`, `tags`, `artisans_count`) VALUES
(6, 'Kulit Nabati & Wayang', 'kulit-nabati-wayang', 'Kulit Nabati & Wayang', 'Penyamakan kulit nabati ramah lingkungan tanpa kromium dari Magetan, serta seni tatah sungging wayang kulit kerbau asli dari sentra Imogiri Yogyakarta.', '2026-11-10 05:43:36', '2026-11-10 05:43:36', NULL, NULL, 'Kayu & Ukiran', 'MAGETAN, IMOGIRI, SUKAREGANG GARUT', NULL, 95),
(7, 'Kriya Logam & Perak', 'kriya-logam-perak', 'Kriya Logam & Perak', 'Teknik filigree perak 925 Kotagede warisan Mataram, cor kuningan bermutu tinggi Juwana Pati, dan kerajinan tempa tembaga relief Tumang Cepogo Boyolali.', '2026-11-10 05:43:36', '2026-11-10 05:43:36', NULL, NULL, 'Logam & Batu', 'KOTAGEDE, JUWANA PATI, TUMANG BOYOLALI', NULL, 80),
(8, 'Batu Mulia & Mutiara Laut', 'batu-mulia-mutiara-laut', 'Batu Mulia & Mutiara Laut', 'Mutiara laut air asin South Sea Pearl budidaya ramah ekosistem teluk Lombok, dipadu asahan batu akik dan kecubung alami pengrajin Martapura Kalimantan Selatan.', '2026-11-10 05:43:36', '2026-11-10 05:43:36', NULL, NULL, 'Logam & Batu', 'SEKARBELA LOMBOK, MARTAPURA KALSEL', NULL, 65);

